// counter.js
export let count = 0;
export function increment() { count++; }
// main.js
import { count, increment } from './counter.js';
console.log(count); // 0
increment();
console.log(count); // 1 (the import is a view of counter.js's binding)
count = 5; // TypeError: Assignment to constant variable (imports are read-only)
CommonJS has no bindings. require() returns whatever module.exports was, and destructuring copies the values:
// counter.cjs
let count = 0;
module.exports = { count, increment() { count++; } };
// main.cjs
const { count, increment } = require('./counter.cjs');
increment();
console.log(count); // 0 (a copy made when the object was created)

